  function bcNearbyPillPoint49(ref,index=0){
  const raw=ref?.id?B.getObject?.({id:ref.id}):null,o=raw?.object||raw?.data||raw;
  if(!o||![o.x,o.y,o.w,o.h].every(v=>Number.isFinite(Number(v))))return null;
  const status=B.canvasStatus?.()||{},view=status.view||{},bounds=view.bounds||{},scale=Math.max(.2,Number(view.scale)||1),pw=176/scale,ph=38/scale,gap=24/scale;
  const x=Number(o.x),y=Number(o.y),w=Math.max(1,Number(o.w)),h=Math.max(1,Number(o.h));
  const candidates=[
    {x:x+w+gap,y:y+Math.min(18/scale,Math.max(0,h-ph))},
    {x:x-pw-gap,y:y+Math.min(18/scale,Math.max(0,h-ph))},
    {x:x+w/2-pw/2,y:y-ph-gap},
    {x:x+w/2-pw/2,y:y+h+gap},
    {x:x+w+gap,y:y+h-ph},
    {x:x-pw-gap,y:y+h-ph},
    {x:x+w+gap,y:y+h/2-ph/2},
    {x:x-pw-gap,y:y+h/2-ph/2}
  ];
  const listed=B.listCanvasObjects?.({limit:240,include_preview:false})?.objects||[],boxes=listed.map(v=>v?.object||v?.data||v).filter(v=>v&&[v.x,v.y,v.w,v.h].every(n=>Number.isFinite(Number(n))));
  const within=p=>!Number.isFinite(Number(bounds.x1))||(p.x>=Number(bounds.x1)+gap&&p.y>=Number(bounds.y1)+gap&&p.x+pw<=Number(bounds.x2)-gap&&p.y+ph<=Number(bounds.y2)-gap);
  const free=p=>boxes.every(b=>p.x+pw+gap<Number(b.x)||p.x-gap>Number(b.x)+Number(b.w)||p.y+ph+gap<Number(b.y)||p.y-gap>Number(b.y)+Number(b.h));
  return candidates.find(p=>within(p)&&free(p))||candidates.find(within)||candidates[index%candidates.length]||candidates[0];
}
