function bcMarkdownToHtml49(source){
  let s=esc(String(source||"")),blocks=[];
  s=s.replace(/```([\s\S]*?)```/g,(_,code)=>`@@BC_CODE_${blocks.push(`<pre><code>${code.trim()}</code></pre>`)-1}@@`);
  const inline=v=>v.replace(/`([^`]+)`/g,"<code>$1</code>").replace(/\*\*([^*]+)\*\*/g,"<strong>$1</strong>").replace(/__([^_]+)__/g,"<strong>$1</strong>").replace(/\*([^*]+)\*/g,"<em>$1</em>").replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener">$1</a>');
  const lines=s.split(/\r?\n/),out=[];let list=null;
  const close=()=>{if(list){out.push(`</${list}>`);list=null}};
  for(const line of lines){
    let m;if((m=line.match(/^(#{1,3})\s+(.+)$/))){close();out.push(`<h${m[1].length}>${inline(m[2])}</h${m[1].length}>`)}
    else if((m=line.match(/^\s*[-*]\s+(.+)$/))){if(list!=="ul"){close();list="ul";out.push("<ul>")}out.push(`<li>${inline(m[1])}</li>`)}
    else if((m=line.match(/^\s*\d+\.\s+(.+)$/))){if(list!=="ol"){close();list="ol";out.push("<ol>")}out.push(`<li>${inline(m[1])}</li>`)}
    else if((m=line.match(/^>\s?(.+)$/))){close();out.push(`<blockquote>${inline(m[1])}</blockquote>`)}
    else if(!line.trim()){close()}
    else{close();out.push(`<p>${inline(line)}</p>`)}
  }
  close();return out.join("").replace(/@@BC_CODE_(\d+)@@/g,(_,i)=>blocks[Number(i)]||"");
}

function bcMarkdownWidgetHtml49(obj){
  if(obj.widgetCollapsed)return `${bcWidgetBar49(obj)}<div class="bc-widget-collapsed-label">Markdown</div>`;
